[100000] = {id = 100000, scroll = 100000, type = 2, teacheid = 0, name = "1-1", cname = "Amnesia", plot_first = "s_1", plot_last = "0", map = "0", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "0", open = "100001_100000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "From\u{0020}that\u{0020}day\u{0020}onward,\u{0020}I\u{0020}lost\u{0020}my\u{0020}past,\u{0020}but\u{0020}in\u{0020}exchange,\u{0020}I\u{0020}gained\u{0020}a\u{0020}power\u{0020}called\u{0020}Synesthesia.\u{0020}For\u{0020}a\u{0020}Navigator,\u{0020}this\u{0020}is\u{0020}undoubtedly\u{0020}a\u{0020}strategic\u{0020}asset,\u{0020}but\u{0020}for\u{0020}a\u{0020}human,\u{0020}it's\u{0020}more\u{0020}like\u{0020}a\u{0020}curse…", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 4, recomlevel = 0, bgpicture = "dialog_s-1", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "Driver\u{0020}upgrade\u{0020}unlocked\u{0020}after\u{0020}clearing\u{0020}level\u{0020}1-7.", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "失忆症", "0", "\u{0020}\u{0020}从那天起，我便失去了过去，但取而代之的是被称之为通感的能力。对领航员的身份而言，这毫无疑问是一项战略级的能力，但对于身为“人”的我而言，这更像是一个诅咒……", "0", "0", "0", "0", "0"},
[100001] = {id = 100001, scroll = 100000, type = 2, teacheid = 0, name = "1-2", cname = "Pre-Battle\u{0020}Briefing", plot_first = "s_2", plot_last = "0", map = "0", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100000", open = "100002_100000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "Gia\u{0020}and\u{0020}I\u{0020}attended\u{0020}the\u{0020}AEGIS\u{0020}mobilization\u{0020}meeting.\u{0020}Officially,\u{0020}Gia\u{0020}is\u{0020}my\u{0020}intelligence\u{0020}officer;\u{0020}unofficially\u{0020}she\u{0020}is\u{0020}my\u{0020}sister\u{0020}suffering\u{0020}from\u{0020}a\u{0020}condition\u{0020}that\u{0020}stole\u{0020}her\u{0020}body's\u{0020}strength.\u{0020}Today\u{0020}marks\u{0020}her\u{0020}first\u{0020}day\u{0020}standing\u{0020}by\u{0020}my\u{0020}side\u{0020}as\u{0020}an\u{0020}officer…", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-2", npctype = 0, npcbanmove = "0", playnumber = 4, recomlevel = 0, bgpicture = "dialog_s-2", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "Driver\u{0020}upgrade\u{0020}unlocked\u{0020}after\u{0020}clearing\u{0020}level\u{0020}1-7.", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "战前会议", "0", "\u{0020}\u{0020}我与我的情报官吉雅，一起来参加了【艾吉斯】的动员会议，虽说是情报官，但实际上吉雅是我的“妹妹”，她患有着四肢无力的病症，今天是她第一天以情报官的身份和我站在一起……", "0", "0", "0", "0", "0"},
