[100008] = {id = 100008, scroll = 100000, type = 2, teacheid = 0, name = "1-9", cname = "Azure\u{0020}Front", plot_first = "s_3", plot_last = "0", map = "0", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100007", open = "100009_100000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "The\u{0020}meeting\u{0020}begins\u{0020}as\u{0020}the\u{0020}Agent\u{0020}announces\u{0020}that\u{0020}war\u{0020}against\u{0020}the\u{0020}Sin\u{0020}is\u{0020}in\u{0020}its\u{0020}final\u{0020}stage.\u{0020}The\u{0020}energy\u{0020}and\u{0020}technology\u{0020}for\u{0020}the\u{0020}DOMINATOR\u{0020}have\u{0020}been\u{0020}fully\u{0020}secured.\u{0020}The\u{0020}large-scale\u{0020}counteroffensive\u{0020}operation,\u{0020}Azure\u{0020}Front,\u{0020}will\u{0020}commence\u{0020}soon…", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-3", npctype = 0, npcbanmove = "0", playnumber = 5, recomlevel = 0, bgpicture = "dialog_s-3", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "Skill\u{0020}upgrade\u{0020}unlocked\u{0020}after\u{0020}clearing\u{0020}level\u{0020}1-11.", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "【苍穹战线】", "0", "\u{0020}\u{0020}会议开始，代理人宣布人类对原罪的战争已经进行到了最后阶段，DOMINATOR（歼星炮）的启动能源与技术已经完全落实，人类的大反击作战【苍穹战线】计划将被启动……", "0", "0", "0", "0", "0"},
[100009] = {id = 100009, scroll = 100000, type = 2, teacheid = 0, name = "1-10", cname = "Dominator", plot_first = "s_4", plot_last = "0", map = "0", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100008", open = "100010_100000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "The\u{0020}goal\u{0020}of\u{0020}Azure\u{0020}Front\u{0020}is\u{0020}to\u{0020}strike\u{0020}the\u{0020}Sin's\u{0020}ancestor,\u{0020}Nevaeh,\u{0020}using\u{0020}the\u{0020}newly\u{0020}developed\u{0020}strategic\u{0020}weapon,\u{0020}DOMINATOR.\u{0020}To\u{0020}accomplish\u{0020}this,\u{0020}the\u{0020}Katya\u{0020}Branch's\u{0020}Ark,\u{0020}with\u{0020}the\u{0020}DOMINATOR\u{0020}onboard,\u{0020}must\u{0020}be\u{0020}launched\u{0020}into\u{0020}lunar\u{0020}orbit.\u{0020}This\u{0020}task\u{0020}falls\u{0020}to\u{0020}the\u{0020}Katya\u{0020}Branch\u{0020}in\u{0020}this\u{0020}operation…", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-4", npctype = 0, npcbanmove = "0", playnumber = 5, recomlevel = 0, bgpicture = "dialog_s-4", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "Skill\u{0020}upgrade\u{0020}unlocked\u{0020}after\u{0020}clearing\u{0020}level\u{0020}1-11.", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "支配者", "0", "\u{0020}\u{0020}【苍穹战线】的真面目是用新研制的战略兵器DOMINATOR直击原罪的始祖【逆爱】，为此需要把搭载DOMINATOR的卡佳支部方舟发射到近月轨道上，这正是本次作战卡佳支部的任务……", "0", "0", "0", "0", "0"},
[100010] = {id = 100010, scroll = 100000, type = 999, teacheid = 51301, name = "1-11", cname = "Attack\u{0020}Target\u{0020}Selection\u{0020}1", plot_first = "0", plot_last = "0", map = "yueqiubiaomian", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100009", open = "100011_100000", player = "11000_3_15_0_1_0_1_0_0_0_0_0_0_0", monster = "210010_3_4_0_0_5_1_0_0_0_0_0_0_0;210010_3_4_0_0_7_1_0_0_0_0_0_0_0;230000_3_1_0_0_12_1_0_0_0_0_0_0_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "Drivers\u{0020}prioritize\u{0020}same-row\u{0020}enemies\u{0020}as\u{0020}their\u{0020}target.\u{0020}If\u{0020}the\u{0020}row\u{0020}is\u{0020}empty,\u{0020}Drivers\u{0020}will\u{0020}base\u{0020}their\u{0020}selection\u{0020}on\u{0020}the\u{0020}row\u{0020}they\u{0020}are\u{0020}in,\u{0020}and\u{0020}attack\u{0020}enemies\u{0020}from\u{0020}the\u{0020}lowest\u{0020}row\u{0020}upwards.", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_teach", npctype = 1, npcbanmove = "0", playnumber = 1, recomlevel = 0, bgpicture = "sdcg_zszd4", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "Skill\u{0020}upgrade\u{0020}unlocked\u{0020}after\u{0020}clearing\u{0020}level\u{0020}1-11.", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "上中下", "0", "\u{0020}\u{0020}驾驶员会优先选取同排敌人为攻击目标。而当同排无敌人时，驾驶员会以自身这排为基础，按照从下往上的顺序去其他排寻找敌人进行攻击。", "0", "0", "0", "0", "0"},
