[100029] = {id = 100029, scroll = 100001, type = 0, teacheid = 0, name = "2-9", cname = "Voice\u{0020}of\u{0020}Mystery", plot_first = "s_9", plot_last = "0", map = "yueqiubiaomian", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100028", open = "100030_100001", player = "0", monster = "220000_1_11_0_1_14_1_0_100020_700_0_100220_300_0;230000_1_11_0_1_12_1_0_100020_700_0_100220_300_0;210010_1_11_0_1_13_1_0_100020_700_0_100220_300_0;230000_1_11_0_1_15_1_0_100020_700_0_100220_300_0;210001_1_11_0_1_18_1_0_100020_700_0_100020_300_0;210000_2_10_0_1_10_1_0_100020_700_0_100220_300_0", consume = "4_100001_8", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110010_5,1_100001_3000", drop = "0", victory = "4_100000_80,1_100001_320", roleexp = "4_100002_80", failure = "4_100001_8", introduction = "A\u{0020}mysterious\u{0020}figure\u{0020}guides\u{0020}me,\u{0020}introducing\u{0020}herself\u{0020}as\u{0020}a\u{0020}descendant\u{0020}of\u{0020}Nevaeh.\u{0020}A\u{0020}rebellious\u{0020}one,\u{0020}she\u{0020}is\u{0020}willing\u{0020}to\u{0020}lend\u{0020}me\u{0020}her\u{0020}power\u{0020}strength\u{0020}to\u{0020}survive\u{0020}the\u{0020}coming\u{0020}wave\u{0020}of\u{0020}Sins.\u{0020}I\u{0020}have\u{0020}no\u{0020}choice\u{0020}but\u{0020}to\u{0020}accept,\u{0020}but\u{0020}it\u{0020}indirectly\u{0020}draws\u{0020}the\u{0020}attention\u{0020}of\u{0020}Nevaeh...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 6, recomlevel = 0, bgpicture = "dialog_s-9", reserve = "0", dangerousenemy = "18_210001", npcheads = "shidifenni", promptdialog = "Auto\u{0020}Battle\u{0020}unlocked\u{0020}after\u{0020}clearing\u{0020}level\u{0020}2-12.", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "谜之声", "0", "\u{0020}\u{0020}神秘的身影引导着我，她自称是【逆爱】的【子嗣】，想要违抗母亲的命令，愿意借给我力量，帮助我度过眼前的原罪潮，我不得不接受，并使用了这份力量，但这也间接导致原罪的首领【逆爱】发现了我……", "0", "0", "0", "0", "0"},
