[100031] = {id = 100031, scroll = 100001, type = 0, teacheid = 0, name = "2-11", cname = "Nevaeh", plot_first = "s_10", plot_last = "0", map = "yueqiubiaomian", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100030", open = "100032_100001", player = "0", monster = "220012_1_11_0_1_16_1_0_100020_1000_0_100220_300_0;230000_1_11_0_1_8_1_0_100020_1000_0_100220_300_0;220012_1_11_0_1_13_1_0_100020_1000_0_100220_300_0;220007_2_10_0_1_1_1_0_100020_1000_0_100220_300_0;230000_1_11_0_1_11_1_0_100020_1000_0_100220_300_0;220012_1_11_0_1_9_1_0_100020_1000_0_100220_300_0", consume = "4_100001_8", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110070_5,1_100001_3000", drop = "0", victory = "4_100000_80,1_100001_320", roleexp = "4_100002_80", failure = "4_100001_8", introduction = "We\u{0020}face\u{0020}her\u{0020}head-on,\u{0020}a\u{0020}figure\u{0020}so\u{0020}towering\u{0020}that\u{0020}makes\u{0020}even\u{0020}the\u{0020}giantesses\u{0020}look\u{0020}like\u{0020}ordinary\u{0020}people.\u{0020}This\u{0020}is\u{0020}humanity's\u{0020}final\u{0020}enemy,\u{0020}Nevaeh,\u{0020}the\u{0020}primordial\u{0020}ancestor\u{0020}of\u{0020}the\u{0020}Sin.\u{0020}I\u{0020}try\u{0020}to\u{0020}interfere\u{0020}with\u{0020}her\u{0020}using\u{0020}my\u{0020}Synesthesia\u{0020}abilities,\u{0020}but\u{0020}I've\u{0020}failed...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 6, recomlevel = 0, bgpicture = "dialog_s-10", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "Auto\u{0020}Battle\u{0020}unlocked\u{0020}after\u{0020}clearing\u{0020}level\u{0020}2-12.", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "逆爱", "0", "\u{0020}\u{0020}我们直面了她，如同山脉一般的巨影横在了我们的面前……使得巨大化的驾驶员们看起来也宛若常人，这便是人类最后的敌人，始祖原罪【逆爱】，我试图用通感的能力干涉她，却失败了……", "0", "0", "0", "0", "0"},
[100032] = {id = 100032, scroll = 100001, type = 15, teacheid = 0, name = "2-12", cname = "Off\u{0020}the\u{0020}Track", plot_first = "s_11", plot_last = "0", map = "yueqiubiaomian_boss", bgm = "9-Battle-niai", unlock = "0_1", front = "100031", open = "100033_100001", player = "0", monster = "600000_3_8_0_1_8_1_0_100355_4000_0_0_0_0", consume = "4_100001_8", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "4_500000_1,1_110031_1,1_100000_50,1_100001_5000", drop = "0", victory = "4_100000_80,1_100001_320", roleexp = "4_100002_80", failure = "4_100001_8", introduction = "At\u{0020}14:58:48\u{0020}on\u{0020}April\u{0020}30,\u{0020}with\u{0020}the\u{0020}help\u{0020}of\u{0020}the\u{0020}mysterious\u{0020}voice,\u{0020}the\u{0020}DOMINATOR\u{0020}is\u{0020}successfully\u{0020}launched...\u{0020}After\u{0020}a\u{0020}long\u{0020}war,\u{0020}humanity\u{0020}has\u{0020}finally\u{0020}won,\u{0020}but\u{0020}why...\u{0020}Why\u{0020}did\u{0020}the\u{0020}detranscription\u{0020}beam\u{0020}miss\u{0020}its\u{0020}target?!\u{0020}The\u{0020}first\u{0020}beam\u{0020}only\u{0020}destroyed\u{0020}the\u{0020}gate\u{0020}beside\u{0020}Nevaeh...", prohibit = "220307;210806;200303;200304;201104;210306", scrollmappos = "0", prohibitskill = "220307;210806;200303;200304;201104;210306", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 6, recomlevel = 0, bgpicture = "dialog_s-11", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "Auto\u{0020}Battle\u{0020}unlocked\u{0020}after\u{0020}clearing\u{0020}level\u{0020}2-12.", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "偏移的轨迹", "0", "\u{0020}\u{0020}4月30日下午2点58分48秒，在谜之声的帮助下，DOMINATOR成功发射……人类终于迎来了漫长的战争的胜利，但是为什么！！……为什么逆转录光线射偏了？！第一发光束，仅仅只摧毁了逆爱身边的一扇【门】", "0", "0", "0", "0", "0"},
[100033] = {id = 100033, scroll = 100001, type = 2, teacheid = 0, name = "2-13", cname = "Curtain\u{0020}Call", plot_first = "s_12", plot_last = "0", map = "0", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100032", open = "100034_100001", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "Death\u{0020}of\u{0020}Nevaeh,\u{0020}confirmed.\u{0020}Her\u{0020}descendant\u{0020}kills\u{0020}her\u{0020}personally,\u{0020}marking\u{0020}the\u{0020}first\u{0020}instance\u{0020}in\u{0020}history\u{0020}where\u{0020}one\u{0020}Sins\u{0020}killed\u{0020}another.\u{0020}Could\u{0020}it\u{0020}be...\u{0020}because\u{0020}the\u{0020}gate\u{0020}was\u{0020}destroyed?!\u{0020}She\u{0020}is\u{0020}ready\u{0020}to\u{0020}launch\u{0020}the\u{0020}second\u{0020}beam...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-12", npctype = 0, npcbanmove = "0", playnumber = 6, recomlevel = 0, bgpicture = "dialog_s-12", reserve = "0", dangerousenemy = "0_0", npcheads = "shidifenni", promptdialog = "Clear\u{0020}level\u{0020}2-19\u{0020}to\u{0020}unlock\u{0020}new\u{0020}events\u{0020}and\u{0020}difficulties.", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "谢幕", "0", "\u{0020}\u{0020}原罪的始祖【逆爱】死亡确认，【逆爱】的【子嗣】通过自己的能力击杀了她，这是历史上第一次出现原罪击杀原罪的事例，难道说是……因为【门】被摧毁的缘故？！【子嗣】开始发射第二DOMINATOR……", "0", "0", "0", "0", "0"},
