[100111] = {id = 100111, scroll = 100010, type = 0, teacheid = 0, name = "3-12", cname = "Valkyrie", plot_first = "1_9", plot_last = "0", map = "haigang_baitian", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100110", open = "100112_100010", player = "0", monster = "200005_2_27_0_2_11_1_0_100020_2400_0_100230_400_0;230003_1_33_0_2_9_1_0_100020_2400_0_100230_400_0;210016_3_24_0_2_13_1_0_100020_2400_0_100230_400_0;200005_2_27_0_2_1_1_0_100020_2400_0_100230_400_0;220014_1_33_0_2_7_1_0_100020_2400_0_100230_400_0;220003_1_33_0_2_16_1_0_100020_2400_0_100230_400_0;220003_1_33_0_2_4_1_0_100020_2400_0_100230_400_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110071_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "Uncertainty\u{0020}has\u{0020}been\u{0020}gnawing\u{0020}at\u{0020}me\u{0020}since\u{0020}the\u{0020}very\u{0020}beginning,\u{0020}stemming\u{0020}from\u{0020}the\u{0020}sea\u{0020}completely\u{0020}shrouded\u{0020}in\u{0020}mist.\u{0020}Meanwhile,\u{0020}Charlissa\u{0020}starts\u{0020}going\u{0020}against\u{0020}my\u{0020}orders\u{0020}and\u{0020}rushes\u{0020}straight\u{0020}into\u{0020}the\u{0020}frontlines...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 7, recomlevel = 0, bgpicture = "dialog_1-9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "女武神", "0", "\u{0020}\u{0020}不安，从作战开始就一直缠绕着我的不安，源自被浓雾完全遮蔽的海面，于此同时，查丽莎终于不再听从我的命令，自顾自地冲到了朱利乌斯身边，也即是正面……", "0", "0", "0", "0", "0"},
[100112] = {id = 100112, scroll = 100010, type = 2, teacheid = 0, name = "3-13", cname = "Turning\u{0020}Point", plot_first = "1_10", plot_last = "0", map = "0", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100111", open = "100113_100010", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "Charlissa,\u{0020}going\u{0020}all\u{0020}out\u{0020}with\u{0020}her\u{0020}firepower,\u{0020}gives\u{0020}me\u{0020}a\u{0020}firsthand\u{0020}look\u{0020}at\u{0020}what\u{0020}true\u{0020}hyper-speed\u{0020}combat\u{0020}looks\u{0020}like.\u{0020}But\u{0020}instead\u{0020}of\u{0020}feeling\u{0020}reassured,\u{0020}her\u{0020}bravery\u{0020}only\u{0020}makes\u{0020}my\u{0020}unease\u{0020}grow\u{0020}stronger.\u{0020}Just\u{0020}as\u{0020}we\u{0020}are\u{0020}arguing,\u{0020}a\u{0020}spider-like\u{0020}Sin\u{0020}appears...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_1-10", npctype = 0, npcbanmove = "0", playnumber = 7, recomlevel = 0, bgpicture = "dialog_1-10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "分歧点", "0", "\u{0020}\u{0020}火力全开的查丽莎，确实让我见识到了什么是真正的【超高速战斗】，但是，她这份神勇的表现并不能让我安心，倒不如说，让我心中的不安加剧了。一只蜘蛛型原罪在我们争论的时候出现了……", "0", "0", "0", "0", "0"},
[100113] = {id = 100113, scroll = 100010, type = 999, teacheid = 51801, name = "3-14", cname = "Self-Destruct\u{0020}Spider", plot_first = "0", plot_last = "0", map = "haigang_baitian", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100112", open = "100114_100010", player = "11000_3_40_0_1_0_1_0_0_0_0_0_0_0;10008_3_40_0_9_0_1_0_0_0_0_0_0_0;13001_3_40_0_1_0_1_0_0_0_0_0_0_0", monster = "210006_3_18_0_0_5_1_0_100035_10000_0_100035_10000_0;210006_3_18_0_0_8_1_0_100035_10000_0_100035_10000_0;210006_3_18_0_0_10_1_0_100035_10000_0_100035_10000_0;210006_3_18_0_0_11_1_0_100035_10000_0_100035_10000_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "On\u{0020}the\u{0020}battlefield,\u{0020}you'll\u{0020}always\u{0020}run\u{0020}into\u{0020}crazy\u{0020}enemies...\u{0020}like\u{0020}those\u{0020}who\u{0020}treat\u{0020}self-destruction\u{0020}as\u{0020}a\u{0020}form\u{0020}of\u{0020}attack...\u{0020}We\u{0020}might\u{0020}not\u{0020}have\u{0020}a\u{0020}perfect\u{0020}solution\u{0020}for\u{0020}them,\u{0020}but\u{0020}we've\u{0020}done\u{0020}the\u{0020}best\u{0020}we\u{0020}can.\u{0020}Sometimes...\u{0020}sacrifices\u{0020}are\u{0020}necessary...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_teach", npctype = 1, npcbanmove = "0", playnumber = 3, recomlevel = 0, bgpicture = "sdcg_zb", reserve = "0", dangerousenemy = "5_210006", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "小小自爆虫", "0", "\u{0020}\u{0020}在战场上，总会有一些疯狂的敌人……比如、将自爆当成是一种攻击方式的……总之，我们可能没有万全之法去应对他们，但我们已经尽量做到了最好。有时候……牺牲也是必要的……", "0", "0", "0", "0", "0"},
