[100117] = {id = 100117, scroll = 100010, type = 0, teacheid = 0, name = "3-18", cname = "Left\u{0020}Behind", plot_first = "1_11", plot_last = "1_11e", map = "haigang_baitian", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100116", open = "100118_100010", player = "0", monster = "230005_2_29_0_2_18_1_0_100020_2700_0_100230_400_0;220017_3_26_0_2_13_1_0_100020_2700_0_100230_400_0;200000_1_35_0_2_2_1_0_100020_2700_0_100230_400_0;220003_1_35_0_2_11_1_0_100020_2700_0_100230_400_0;200009_1_35_0_2_3_1_0_100020_2700_0_100030_400_0;210006_2_29_0_2_6_1_0_100020_2700_0_100030_400_0;200000_1_35_0_2_4_1_0_100020_2700_0_100230_400_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110010_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "Toxic\u{0020}gas\u{0020}pours\u{0020}out\u{0020}after\u{0020}the\u{0020}spider's\u{0020}explosion,\u{0020}spreading\u{0020}across\u{0020}the\u{0020}battlefield.\u{0020}I\u{0020}quickly\u{0020}maneuver\u{0020}to\u{0020}higher\u{0020}ground,\u{0020}while\u{0020}Franca\u{0020}leads\u{0020}the\u{0020}civilians\u{0020}away\u{0020}from\u{0020}the\u{0020}poison.\u{0020}But\u{0020}by\u{0020}then,\u{0020}the\u{0020}formation\u{0020}has\u{0020}already\u{0020}broken,\u{0020}and\u{0020}as\u{0020}a\u{0020}support\u{0020}unit,\u{0020}Franca\u{0020}is\u{0020}the\u{0020}first\u{0020}to\u{0020}be\u{0020}attacked\u{0020}and\u{0020}lost\u{0020}contact...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 7, recomlevel = 0, bgpicture = "dialog_1-11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "失航", "0", "\u{0020}\u{0020}从爆炸的蜘蛛身体内涌出的有毒气体向四周扩散，我操纵着机动装置急速拉高了位置，弗兰卡带着民众向远离毒气的方向转移，但此时的战场的阵型已经被破坏，作为支援型的弗兰卡率先受到了袭击，失去了联络……", "0", "0", "0", "0", "0"},
[100118] = {id = 100118, scroll = 100010, type = 2, teacheid = 0, name = "3-19", cname = "Ignited\u{0020}Flame", plot_first = "1_12", plot_last = "0", map = "0", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100117", open = "100119_100011", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "Franca\u{0020}fights\u{0020}desperately\u{0020}to\u{0020}protect\u{0020}the\u{0020}people,\u{0020}and\u{0020}at\u{0020}that\u{0020}moment,\u{0020}Charlissa\u{0020}finally\u{0020}realizes\u{0020}her\u{0020}mistake\u{0020}and\u{0020}arrives\u{0020}on\u{0020}the\u{0020}scene.\u{0020}Seeing\u{0020}Franca's\u{0020}condition,\u{0020}she\u{0020}charges\u{0020}into\u{0020}the\u{0020}toxic\u{0020}mist,\u{0020}furious,\u{0020}hunting\u{0020}down\u{0020}the\u{0020}attacker—\u{0020}the\u{0020}mantis-type\u{0020}Sin...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_1-12", npctype = 0, npcbanmove = "0", playnumber = 7, recomlevel = 0, bgpicture = "dialog_1-12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "心火燃起", "0", "\u{0020}\u{0020}弗兰卡为了守护人们的安危而死死支撑着，此时终于意识到自己失误的查丽莎赶到了现场，见识到了弗兰卡惨状，愤怒之下的她追着袭击者——螳螂型原罪深入了毒雾中……", "0", "0", "0", "0", "0"},
