[100122] = {id = 100122, scroll = 100011, type = 2, teacheid = 0, name = "4-4", cname = "Confrontation", plot_first = "1_13", plot_last = "0", map = "0", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100121", open = "100123_100011", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "In\u{0020}the\u{0020}thick\u{0020}fog,\u{0020}Charlissa\u{0020}and\u{0020}the\u{0020}Sin\u{0020}face\u{0020}off\u{0020}in\u{0020}a\u{0020}showdown—a\u{0020}hunter\u{0020}and\u{0020}a\u{0020}prey.\u{0020}But\u{0020}who\u{0020}is\u{0020}the\u{0020}prey?\u{0020}That\u{0020}remains\u{0020}unclear.\u{0020}Both\u{0020}keep\u{0020}testing\u{0020}the\u{0020}other's\u{0020}limits.\u{0020}Charlissa,\u{0020}determined\u{0020}to\u{0020}fight\u{0020}without\u{0020}fear\u{0020}of\u{0020}injury,\u{0020}seems\u{0020}ready\u{0020}to\u{0020}go\u{0020}down\u{0020}with\u{0020}the\u{0020}Sin\u{0020}in\u{0020}a\u{0020}final\u{0020}clash...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_1-13", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-13", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "两方对峙", "0", "\u{0020}\u{0020}浓雾中，查丽莎与原罪正在对峙着，这是一场猎杀者和猎物的对决，但究竟谁是猎物还犹未可知，双方不断地试探，查丽莎抱持着以伤换伤的意志，似乎打算与原罪同归于尽……", "0", "0", "0", "0", "0"},
[100123] = {id = 100123, scroll = 100011, type = 999, teacheid = 51901, name = "4-5", cname = "Class\u{0020}Advantage", plot_first = "0", plot_last = "0", map = "haigang_baitian", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100122", open = "100124_100011", player = "10012_4_30_0_1_0_1_0_0_0_0_0_0_0;11017_5_30_0_0_0_1_0_0_0_0_0_0_0", monster = "210008_3_10_0_6_3_1_0_0_0_0_100032_10000_0;210008_3_10_0_6_5_1_0_0_0_0_100032_10000_0;210008_3_10_0_6_7_1_0_0_0_0_100032_10000_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "There\u{0020}are\u{0020}certain\u{0020}Drivers\u{0020}who\u{0020}specialize\u{0020}in\u{0020}dealing\u{0020}with\u{0020}specific\u{0020}types\u{0020}of\u{0020}Sin.\u{0020}They\u{0020}may\u{0020}not\u{0020}be\u{0020}the\u{0020}strongest,\u{0020}and\u{0020}their\u{0020}abilities\u{0020}have\u{0020}some\u{0020}limitations,\u{0020}but\u{0020}they\u{0020}excel\u{0020}at\u{0020}handling\u{0020}particular\u{0020}enemies.\u{0020}If\u{0020}you\u{0020}send\u{0020}these\u{0020}specialized\u{0020}Drivers\u{0020}to\u{0020}face\u{0020}enemies\u{0020}they're\u{0020}not\u{0020}equipped\u{0020}to\u{0020}deal\u{0020}with,\u{0020}you\u{0020}could\u{0020}find\u{0020}yourself\u{0020}in\u{0020}a\u{0020}tough\u{0020}spot.", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_teach", npctype = 1, npcbanmove = "0", playnumber = 2, recomlevel = 0, bgpicture = "sdcg_zytg1", reserve = "0", dangerousenemy = "3_210008", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "职业特攻", "0", "\u{0020}\u{0020}有这样一类特殊的驾驶员与原罪。她们本身并不算强，技能也有着一定的限制，但她们较为擅长应对某一类型的敌人。如果你正好派出她们擅长应对的类型的驾驶员进入站场，可能会吃上不小的苦头。", "0", "0", "0", "0", "0"},
