[100127] = {id = 100127, scroll = 100011, type = 0, teacheid = 0, name = "4-9", cname = "Coordination", plot_first = "1_14", plot_last = "1_14e", map = "haigang_huanghun", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100126", open = "100128_100011", player = "0", monster = "230009_2_40_0_2_18_1_0_100020_2900_0_100230_500_0;220009_2_33_0_2_7_1_0_100020_2900_0_100230_500_0;230006_2_33_0_2_16_1_0_100020_2900_0_100230_500_0;210015_3_29_0_2_14_1_0_100020_2900_0_100230_500_0;230009_2_40_0_2_5_1_0_100020_2900_0_100230_500_0;200001_2_40_0_2_2_1_0_100020_2900_0_100230_500_0;220000_2_40_0_2_15_1_0_100020_2900_0_100230_500_0;200001_2_40_0_2_9_1_0_100020_2900_0_100230_500_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110010_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "Both\u{0020}sides\u{0020}aim\u{0020}for\u{0020}each\u{0020}other's\u{0020}heads,\u{0020}ready\u{0020}to\u{0020}land\u{0020}a\u{0020}fatal\u{0020}blow—but\u{0020}the\u{0020}showdown\u{0020}is\u{0020}abruptly\u{0020}interrupted\u{0020}by\u{0020}an\u{0020}unexpected\u{0020}figure.\u{0020}Julius\u{0020}arrives\u{0020}just\u{0020}in\u{0020}time,\u{0020}causing\u{0020}the\u{0020}mantis-type\u{0020}Sin\u{0020}to\u{0020}retreat\u{0020}once\u{0020}again.\u{0020}Navigator\u{0020}has\u{0020}establish\u{0020}connection\u{0020}to\u{0020}Charlissa\u{0020}via\u{0020}Synesthesia\u{0020}to\u{0020}share\u{0020}her\u{0020}pain...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-14", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "协同", "0", "\u{0020}\u{0020}双方互相瞄准对方的头部，给予对方致命一击——但这场绝对却被突如其来的身影中断了，朱利乌斯及时赶到了现场，螳螂型原罪再度撤走，领航与查丽莎建立了【通感】分担了她的痛苦……", "0", "0", "0", "0", "0"},
[100128] = {id = 100128, scroll = 100011, type = 0, teacheid = 0, name = "4-10", cname = "Major\u{0020}Sin", plot_first = "1_15", plot_last = "0", map = "haigang_huanghun", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100127", open = "100129_100011", player = "0", monster = "230009_2_41_0_2_3_1_0_100030_3100_0_100230_500_0;200001_2_41_0_2_5_1_0_100030_3100_0_100230_500_0;230006_2_35_0_2_1_1_0_100030_3100_0_100230_500_0;210008_2_35_0_2_8_1_0_100030_3100_0_100230_500_0;230009_2_41_0_2_17_1_0_100030_3100_0_100230_500_0;210015_3_31_0_2_14_1_0_100030_3100_0_100230_500_0;210002_2_41_0_2_12_1_0_100030_3100_0_100230_500_0;210002_2_41_0_2_10_1_0_100030_3100_0_100230_500_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110081_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "My\u{0020}worst\u{0020}fears\u{0020}have\u{0020}come\u{0020}true.\u{0020}The\u{0020}Major\u{0020}Sin,\u{0020}Sobek,\u{0020}has\u{0020}landed\u{0020}from\u{0020}the\u{0020}sea.\u{0020}Conventional\u{0020}ground\u{0020}forces\u{0020}can't\u{0020}even\u{0020}scratch\u{0020}it,\u{0020}only\u{0020}provoking\u{0020}it\u{0020}further.\u{0020}After\u{0020}letting\u{0020}out\u{0020}a\u{0020}deafening\u{0020}roar,\u{0020}its\u{0020}attention\u{0020}turns\u{0020}toward\u{0020}us,\u{0020}who\u{0020}are\u{0020}evacuating.", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-15", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "准罪级", "0", "\u{0020}\u{0020}我一直以来的担忧成为了现实，准罪级原罪——【索贝克】从海中登陆了，地面部队的常规火力无法对它造成一丝一毫的伤害，反而激怒了它，而在它发泄一通吼，把目光放在正在撤离的我们身上。", "0", "0", "0", "0", "0"},
[100129] = {id = 100129, scroll = 100011, type = 0, teacheid = 0, name = "4-11", cname = "Shield\u{0020}of\u{0020}the\u{0020}People", plot_first = "1_16", plot_last = "0", map = "haigang_huanghun", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100128", open = "100130_100011", player = "0", monster = "200001_2_41_0_2_5_1_0_100030_3100_0_100230_500_0;200009_2_41_0_2_16_1_0_100030_3100_0_100030_500_0;210008_2_35_0_2_10_1_0_100030_3100_0_100230_500_0;210015_3_31_0_2_11_1_0_100030_3100_0_100230_500_0;200009_2_41_0_2_18_1_0_100030_3100_0_100030_500_0;220000_2_41_0_2_12_1_0_100030_3100_0_100230_500_0;220000_2_41_0_2_3_1_0_100030_3100_0_100230_500_0;220009_2_35_0_2_8_1_0_100030_3100_0_100230_500_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110071_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "In\u{0020}five\u{0020}minutes,\u{0020}Sobek\u{0020}will\u{0020}make\u{0020}contact\u{0020}with\u{0020}our\u{0020}team.\u{0020}I\u{0020}make\u{0020}a\u{0020}quick\u{0020}decision—Charlissa\u{0020}will\u{0020}clear\u{0020}out\u{0020}the\u{0020}surrounding\u{0020}Sins,\u{0020}and\u{0020}then\u{0020}we'll\u{0020}have\u{0020}the\u{0020}civilians\u{0020}evacuate\u{0020}first.\u{0020}We\u{0020}need\u{0020}to\u{0020}hold\u{0020}off\u{0020}Sobek\u{0020}right\u{0020}here!", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-16", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "民众之盾", "0", "\u{0020}\u{0020}预计在五分钟后，【索贝尔】会与我们小队进行第一次接触，我下了一个决断，让查丽莎迅速清理周边的原罪的，然后让平民们先撤离，我们要在这里拦下【索贝尔】！", "0", "0", "0", "0", "0"},
[100130] = {id = 100130, scroll = 100011, type = 0, teacheid = 0, name = "4-12", cname = "Shield\u{0020}of\u{0020}the\u{0020}People\u{0020}-\u{0020}1", plot_first = "0", plot_last = "0", map = "haigang_huanghun", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100129", open = "100131_100011", player = "0", monster = "230009_2_41_0_2_17_1_0_100030_3100_0_100230_500_0;210008_2_35_0_2_8_1_0_100030_3100_0_100230_500_0;210008_2_35_0_2_3_1_0_100030_3100_0_100230_500_0;210015_3_32_0_2_5_1_0_100030_3100_0_100230_500_0;200001_2_41_0_2_7_1_0_100030_3100_0_100230_500_0;220000_2_41_0_2_10_1_0_100030_3100_0_100230_500_0;220000_2_41_0_2_15_1_0_100030_3100_0_100230_500_0;220000_2_41_0_2_16_1_0_100030_3100_0_100230_500_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110010_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "0", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "民众之盾-1", "0", "0", "0", "0", "0", "0", "0"},
[100131] = {id = 100131, scroll = 100011, type = 0, teacheid = 0, name = "4-13", cname = "Shield\u{0020}of\u{0020}the\u{0020}People\u{0020}-\u{0020}2", plot_first = "0", plot_last = "0", map = "haigang_huanghun", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100130", open = "100132_100011", player = "0", monster = "220009_2_35_0_2_3_1_0_100030_3100_0_100230_500_0;230006_2_35_0_2_11_1_0_100030_3100_0_100230_500_0;210015_3_32_0_2_7_1_0_100030_3100_0_100230_500_0;200009_2_41_0_2_18_1_0_100030_3100_0_100030_500_0;220000_2_41_0_2_16_1_0_100030_3100_0_100230_500_0;210002_2_41_0_2_10_1_0_100030_3100_0_100230_500_0;200009_2_41_0_2_9_1_0_100030_3100_0_100030_500_0;220000_2_41_0_2_1_1_0_100030_3100_0_100230_500_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110081_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "0", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "0", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "民众之盾-2", "0", "0", "0", "0", "0", "0", "0"},
[100132] = {id = 100132, scroll = 100011, type = 0, teacheid = 0, name = "4-14", cname = "Soldier", plot_first = "0", plot_last = "1_17e", map = "haigang_huanghun", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100131", open = "100133_100011", player = "0", monster = "200009_2_43_0_2_9_1_0_100030_3300_0_100030_500_0;200001_2_43_0_2_3_1_0_100030_3300_0_100230_500_0;210015_2_37_0_2_5_1_0_100030_3300_0_100230_500_0;230009_2_43_0_2_7_1_0_100030_3300_0_100230_500_0;210008_2_37_0_2_14_1_0_100030_3300_0_100230_500_0;220000_2_43_0_2_13_1_0_100030_3300_0_100230_500_0;210015_3_33_0_2_1_1_0_100030_3300_0_100230_500_0;210008_2_43_0_2_11_1_0_100030_3300_0_100230_500_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "1_100000_30,1_110071_5,1_100001_3000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "Fortunately,\u{0020}the\u{0020}soldier\u{0020}I\u{0020}saved\u{0020}earlier\u{0020}has\u{0020}now\u{0020}taken\u{0020}over\u{0020}the\u{0020}task\u{0020}of\u{0020}leading\u{0020}the\u{0020}evacuation.\u{0020}Thanks\u{0020}to\u{0020}him,\u{0020}we\u{0020}can\u{0020}focus\u{0020}on\u{0020}fighting.\u{0020}Even\u{0020}though\u{0020}we're\u{0020}not\u{0020}in\u{0020}the\u{0020}same\u{0020}organization,\u{0020}we\u{0020}share\u{0020}the\u{0020}same\u{0020}goal,\u{0020}and\u{0020}that's\u{0020}enough...\u{0020}The\u{0020}battle\u{0020}against\u{0020}Sobek\u{0020}officially\u{0020}begins.", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-17", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "士兵", "0", "\u{0020}\u{0020}所幸的是，我之前救下的士兵此时接过了了带领人群撤离的任务，托他的福，我们这边也能好好地战斗。尽管，我们与他们并不属于一个体制，但，我们的目的是相同的，这就足够了……【索贝尔】讨伐战正式开始。", "0", "0", "0", "0", "0"},
[100133] = {id = 100133, scroll = 100011, type = 2, teacheid = 0, name = "4-15", cname = "Interception\u{0020}Battle", plot_first = "1_18", plot_last = "0", map = "0", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100132", open = "100134_100011", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "The\u{0020}pressure\u{0020}and\u{0020}life-or-death\u{0020}tension\u{0020}brought\u{0020}by\u{0020}such\u{0020}a\u{0020}powerful\u{0020}enemy\u{0020}is\u{0020}suffocating,\u{0020}but\u{0020}at\u{0020}the\u{0020}same\u{0020}time,\u{0020}the\u{0020}four\u{0020}of\u{0020}us—each\u{0020}with\u{0020}different\u{0020}personalities—have\u{0020}started\u{0020}to\u{0020}bond\u{0020}and\u{0020}mesh.\u{0020}This\u{0020}encounter\u{0020}marks\u{0020}the\u{0020}beginning\u{0020}of\u{0020}our\u{0020}squad's\u{0020}development.\u{0020}Together,\u{0020}we'll\u{0020}overcome\u{0020}this\u{0020}challenge\u{0020}and\u{0020}turn\u{0020}Sobek,\u{0020}the\u{0020}Major\u{0020}Sin,\u{0020}into\u{0020}the\u{0020}\"prey\".", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_1-18", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-18", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "阻截战", "0", "\u{0020}\u{0020}强敌带给我们的压迫感、生死感，让人窒息，但同时，经过重重筛选进入这支特别小队性格迥异的三人却因此开始磨合，小队的雏形在这场遭遇战中显现，我们将会跨过这道难关，把准罪级原罪【索贝尔】化为“食粮”。", "0", "0", "0", "0", "0"},
[100134] = {id = 100134, scroll = 100011, type = 15, teacheid = 0, name = "4-16", cname = "Transformed\u{0020}into\u{0020}a\u{0020}Monster", plot_first = "1_19", plot_last = "0", map = "haigang_boss_huanghun", bgm = "15-Battle-Sobek_MP3", unlock = "0_1", front = "100133", open = "100135_100011", player = "0", monster = "600001_3_35_0_5_8_1_0_100155_675_0_100355_675_0", consume = "4_100001_12", frequency = 0, condition = "0_9_1,2_45_32,0_2_12", reward = "4_500001_1,1_110031_1,1_100000_50,1_100001_5000", drop = "0", victory = "4_100000_120,1_100001_480", roleexp = "4_100002_120", failure = "4_100001_12", introduction = "I\u{0020}decide\u{0020}to\u{0020}push\u{0020}the\u{0020}frontlines\u{0020}to\u{0020}the\u{0020}shore,\u{0020}where\u{0020}there\u{0020}would\u{0020}be\u{0020}fewer\u{0020}things\u{0020}to\u{0020}worry\u{0020}about.\u{0020}The\u{0020}Drivers\u{0020}start\u{0020}working\u{0020}together,\u{0020}and\u{0020}in\u{0020}the\u{0020}battle\u{0020}against\u{0020}the\u{0020}monsters,\u{0020}they\u{0020}are\u{0020}willing\u{0020}to\u{0020}transform\u{0020}into\u{0020}monsters\u{0020}themselves.\u{0020}Such\u{0020}is\u{0020}humanity...", prohibit = "220307;210806;200303;200304;201104;210306", scrollmappos = "0", prohibitskill = "220307;210806;200303;200304;201104;210306", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-19", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "化身为怪物", "0", "\u{0020}\u{0020}我准备把战线拉扯到海边，这样需要顾及的东西就少了很多，驾驶员们开始不断地配合着，为了打倒怪物——自身不惜化为怪物，这就是我们人类啊……", "0", "0", "0", "0", "0"},
[100135] = {id = 100135, scroll = 100011, type = 2, teacheid = 0, name = "4-17", cname = "The\u{0020}Survivor", plot_first = "1_20", plot_last = "0", map = "0", bgm = "19-Battle-Warehouse_MP3", unlock = "0_1", front = "100134", open = "100200_100020", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "In\u{0020}the\u{0020}first\u{0020}battle\u{0020}of\u{0020}the\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force,\u{0020}we\u{0020}triumph\u{0020}with\u{0020}the\u{0020}death\u{0020}of\u{0020}the\u{0020}Major\u{0020}Sin\u{0020}Sobek.\u{0020}But\u{0020}the\u{0020}mist\u{0020}still\u{0020}hasn't\u{0020}cleared,\u{0020}and\u{0020}from\u{0020}the\u{0020}fog\u{0020}emerged\u{0020}a\u{0020}massive\u{0020}figure—a\u{0020}battered\u{0020}girl...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_1-20", npctype = 0, npcbanmove = "0", playnumber = 8, recomlevel = 0, bgpicture = "dialog_1-20", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "生还者", "0", "\u{0020}\u{0020}多瑙特别联合部队的首战，以准罪级原罪【索贝尔】的死亡告捷，但是浓雾却尚未散开，从雾中又有一道巨大的身影缓缓走出，是一位伤痕累累的少女……", "0", "0", "0", "0", "0"},
[100200] = {id = 100200, scroll = 100020, type = 2, teacheid = 0, name = "5-1", cname = "Attendees\u{0020}", plot_first = "2_1", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100135", open = "100201_100020", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "Dolores,\u{0020}a\u{0020}Driver\u{0020}from\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad,\u{0020}is\u{0020}the\u{0020}girl\u{0020}we\u{0020}saved\u{0020}from\u{0020}the\u{0020}haze.\u{0020}She\u{0020}reveals\u{0020}the\u{0020}truth\u{0020}to\u{0020}us—that\u{0020}the\u{0020}fog\u{0020}hasn't\u{0020}been\u{0020}lifted\u{0020}yet,\u{0020}and\u{0020}a\u{0020}new\u{0020}Great\u{0020}Sin\u{0020}has\u{0020}been\u{0020}born.", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_2-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "与会人员\u{0020}", "0", "\u{0020}\u{0020}多洛莉丝，她是第三研究室防卫队的驾驶员，也是在雾中被我们救出的少女，我们从她口中得知了浓雾仍未散去的真相，又有一只【高等原罪】诞生了。", "0", "0", "0", "0", "0"},
[100201] = {id = 100201, scroll = 100020, type = 2, teacheid = 0, name = "5-2", cname = "Lost\u{0020}Memories", plot_first = "2_2", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100200", open = "100202_100020", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "Before\u{0020}our\u{0020}sortie,\u{0020}Dolores\u{0020}seems\u{0020}unable\u{0020}to\u{0020}remember\u{0020}anything\u{0020}due\u{0020}to\u{0020}the\u{0020}effects\u{0020}of\u{0020}the\u{0020}haze.\u{0020}She\u{0020}believes\u{0020}herself\u{0020}to\u{0020}be\u{0020}a\u{0020}deserter\u{0020}from\u{0020}the\u{0020}Third\u{0020}Laboratory's\u{0020}defense\u{0020}team,\u{0020}but\u{0020}we\u{0020}don't\u{0020}see\u{0020}her\u{0020}that\u{0020}way.\u{0020}We\u{0020}begin\u{0020}to\u{0020}comfort\u{0020}her...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_2-2", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "记忆失却", "0", "\u{0020}\u{0020}出击前的准备，多洛莉丝似乎因为苍雾的影响什么都想不起来了，她似乎认为自己是第三研究室防卫队的逃兵，大家并不那么认为，并且开始开导多洛莉丝……", "0", "0", "0", "0", "0"},
[100202] = {id = 100202, scroll = 100020, type = 999, teacheid = 52001, name = "5-3", cname = "Mobility", plot_first = "0", plot_last = "0", map = "haizhan_yewan", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100201", open = "100203_100020", player = "11003_3_30_1_10_0_1_0_0_0_0_0_0_0;11006_3_30_0_9_0_1_0_0_0_0_0_0_0;13000_5_50_1_9_0_1_0_0_0_0_0_0_0", monster = "210003_3_24_0_0_2_1_0_100035_10000_0_100035_10000_0;210003_3_24_0_0_4_1_0_100035_10000_0_100035_10000_0;210003_3_24_0_0_6_1_0_100035_10000_0_100035_10000_0;210003_3_24_0_0_8_1_0_100035_10000_0_100035_10000_0", consume = "4_100001_0", frequency = 0, condition = "0_9_1,2_666_34,0_9_33", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "Spin!\u{0020}Jump!\u{0020}Drivers\u{0020}or\u{0020}Sins\u{0020}with\u{0020}high\u{0020}mobility\u{0020}can\u{0020}easily\u{0020}dodge\u{0020}enemy\u{0020}attacks.\u{0020}They\u{0020}might\u{0020}not\u{0020}avoid\u{0020}all\u{0020}the\u{0020}damage,\u{0020}but\u{0020}it\u{0020}sure\u{0020}looks\u{0020}cool,\u{0020}right?", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_teach", npctype = 1, npcbanmove = "0", playnumber = 3, recomlevel = 0, bgpicture = "sdcg_zszd13", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "机动力", "0", "\u{0020}\u{0020}旋转！跳跃！拥有着高机动力的驾驶员或原罪很容易就能够闪避敌人的攻击。虽然并不能完全避免伤害，但这也足够帅气了，不是嘛。", "0", "0", "0", "0", "0"},
