[100222] = {id = 100222, scroll = 100020, type = 0, teacheid = 0, name = "5-23", cname = "Angelica", plot_first = "2_8", plot_last = "2_8e", map = "haizhan_yewan", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100221", open = "100223_100020", player = "0", monster = "220002_3_42_0_3_3_1_0_100031_4100_0_100240_1500_0;220001_2_50_0_3_18_1_0_100031_4100_0_100240_1500_0;200003_2_47_0_3_8_1_0_100031_4100_0_100240_1500_0;210004_2_50_0_3_4_1_0_100031_4100_0_100240_1500_0;230008_2_50_0_3_7_1_0_100031_4100_0_100240_1500_0;200003_2_47_0_3_12_1_0_100031_4100_0_100240_1500_0;210004_2_50_0_3_13_1_0_100031_4100_0_100240_1500_0;200006_2_47_0_3_17_1_0_100031_4100_0_100240_1500_0;220002_3_42_0_3_11_1_0_100031_4100_0_100240_1500_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "1_100000_30,1_110010_5,1_100001_3000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "A\u{0020}Sin\u{0020}lies\u{0020}in\u{0020}wait\u{0020}on\u{0020}our\u{0020}return\u{0020}journey,\u{0020}seemingly\u{0020}launching\u{0020}a\u{0020}premeditated\u{0020}attack\u{0020}on\u{0020}us.\u{0020}To\u{0020}alleviate\u{0020}Dolores's\u{0020}pain,\u{0020}I\u{0020}establish\u{0020}Synesthesia\u{0020}with\u{0020}her.\u{0020}A\u{0020}sadness,\u{0020}almost\u{0020}mournful,\u{0020}surges\u{0020}into\u{0020}my\u{0020}mind\u{0020}like\u{0020}a\u{0020}river...\u{0020}Soon\u{0020}after,\u{0020}we\u{0020}encounter\u{0020}the\u{0020}giant\u{0020}Sin—", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "安洁莉卡", "0", "\u{0020}\u{0020}原罪潜伏在我们返程路上，像是有预谋地针对着我们发起袭击，我为了缓解多洛莉丝的痛苦，与她建立了【通感】，悲伤到近乎哀恸的情绪如河流般奔入我的脑中……随后我们遭遇了巨大的原罪——", "0", "0", "0", "0", "0"},
[100223] = {id = 100223, scroll = 100020, type = 0, teacheid = 0, name = "5-24", cname = "First\u{0020}Contact", plot_first = "0", plot_last = "2_9e", map = "haizhan_yewan", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100222", open = "100224_100020", player = "0", monster = "210009_2_47_0_3_3_1_0_100031_4100_0_100240_1500_0;220005_2_50_0_3_2_1_0_100031_4100_0_100240_1500_0;200012_2_50_0_3_18_1_0_100031_4100_0_100240_1500_0;220003_2_50_0_3_6_1_0_100031_4100_0_100240_1500_0;200008_3_42_0_3_16_1_0_100031_4100_0_100240_1500_0;220009_2_47_0_3_12_1_0_100031_4100_0_100240_1500_0;210015_3_42_0_3_17_1_0_100031_4100_0_100240_1500_0;220005_2_50_0_3_1_1_0_100031_4100_0_100240_1500_0;210009_2_47_0_3_8_1_0_100031_4100_0_100240_1500_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "1_100000_30,1_110082_5,1_100001_3000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "We\u{0020}clash\u{0020}with\u{0020}the\u{0020}serpent-like\u{0020}giant\u{0020}Sin,\u{0020}but\u{0020}we\u{0020}has\u{0020}already\u{0020}fought\u{0020}several\u{0020}rounds\u{0020}before.\u{0020}The\u{0020}remaining\u{0020}Nimbus\u{0020}energy\u{0020}is\u{0020}insufficient\u{0020}for\u{0020}a\u{0020}full-scale\u{0020}assault.\u{0020}When\u{0020}Charlissa\u{0020}finds\u{0020}an\u{0020}opportunity\u{0020}to\u{0020}inflict\u{0020}damage\u{0020}on\u{0020}the\u{0020}giant\u{0020}Sin,\u{0020}we\u{0020}choose\u{0020}to\u{0020}withdraw\u{0020}quickly...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-9", reserve = "0", dangerousenemy = "16_200008", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "第一类接触", "0", "\u{0020}\u{0020}我们与海蛇般的巨大原罪展开了交锋，但是我们之前已经经历过几轮战斗，剩下的尼姆比斯液不足以支撑我们进行一场讨伐战，在查丽莎找到机会给予巨大原罪创伤的时候，我们选择了迅速撤离……", "0", "0", "0", "0", "0"},
[100224] = {id = 100224, scroll = 100020, type = 2, teacheid = 0, name = "5-25", cname = "Interlude\u{0020}I", plot_first = "2_10", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100223", open = "100225_100020", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "Fear,\u{0020}despair,\u{0020}sorrow,\u{0020}and—courage.\u{0020}These\u{0020}are\u{0020}the\u{0020}impressions\u{0020}I\u{0020}have\u{0020}of\u{0020}this\u{0020}memory,\u{0020}so\u{0020}subjective\u{0020}that\u{0020}it\u{0020}could\u{0020}be\u{0020}considered\u{0020}my\u{0020}personal\u{0020}view.\u{0020}The\u{0020}story\u{0020}of\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad's\u{0020}captain,\u{0020}Angelica,\u{0020}began\u{0020}with\u{0020}a\u{0020}dramatic\u{0020}start,\u{0020}but\u{0020}it\u{0020}quickly\u{0020}comes\u{0020}to\u{0020}an\u{0020}end...\u{0020}Or\u{0020}does\u{0020}it\u{0020}really\u{0020}end...?", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_2-10", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "幕间Ⅰ", "0", "\u{0020}\u{0020}恐惧、绝望、哀痛，以及——勇气，这是我对这段记忆主观到可以说是一己之见的印象，第三研究院防卫队队长，安洁莉卡的故事拉开了序幕，而又快速落幕……真的落幕了吗……？", "0", "0", "0", "0", "0"},
[100225] = {id = 100225, scroll = 100020, type = 0, teacheid = 0, name = "5-26", cname = "The\u{0020}Meaning\u{0020}of\u{0020}Escape", plot_first = "2_11", plot_last = "0", map = "haizhan_yewan", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100224", open = "100226_100020", player = "0", monster = "210015_3_42_0_3_14_1_0_100031_4100_0_100240_1500_0;220009_2_47_0_3_12_1_0_100031_4100_0_100240_1500_0;200008_3_42_0_3_5_1_0_100031_4100_0_100240_1500_0;210009_2_47_0_3_2_1_0_100031_4100_0_100240_1500_0;210009_2_47_0_3_3_1_0_100031_4100_0_100240_1500_0;220005_2_50_0_3_9_1_0_100031_4100_0_100240_1500_0;220005_2_50_0_3_18_1_0_100031_4100_0_100240_1500_0;200012_2_50_0_3_7_1_0_100031_4100_0_100240_1500_0;220003_2_50_0_3_16_1_0_100031_4100_0_100240_1500_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "1_100000_30,1_110072_5,1_100001_3000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "We\u{0020}meet\u{0020}the\u{0020}Moon\u{0020}Corona\u{0020}Squad\u{0020}waiting\u{0020}for\u{0020}us\u{0020}on\u{0020}the\u{0020}outskirts\u{0020}of\u{0020}the\u{0020}haze.\u{0020}At\u{0020}this\u{0020}point,\u{0020}Dolores\u{0020}has\u{0020}finally\u{0020}eased\u{0020}her\u{0020}pain\u{0020}and\u{0020}regained\u{0020}her\u{0020}memories—her\u{0020}true\u{0020}mission.\u{0020}She\u{0020}is\u{0020}a\u{0020}key,\u{0020}the\u{0020}only\u{0020}one\u{0020}who\u{0020}could\u{0020}unlock\u{0020}the\u{0020}door\u{0020}to\u{0020}the\u{0020}Third\u{0020}Laboratory.", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "逃走的意义", "0", "\u{0020}\u{0020}我们在苍雾的外围遇见了等待着我们的月冕小队，此时的多洛莉丝也终于从痛苦中缓和了过了，并找回了属于她的记忆，属于她的使命——她是一一枚钥匙，只有她能开通通往第三实验室的大门。", "0", "0", "0", "0", "0"},
[100226] = {id = 100226, scroll = 100020, type = 2, teacheid = 0, name = "5-27", cname = "Savior", plot_first = "2_12", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100225", open = "100227_100020", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "The\u{0020}captain\u{0020}of\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}activates\u{0020}the\u{0020}defense\u{0020}system\u{0020}to\u{0020}protect\u{0020}the\u{0020}core\u{0020}area,\u{0020}giving\u{0020}us\u{0020}twenty-four\u{0020}hours\u{0020}to\u{0020}prepare\u{0020}for\u{0020}our\u{0020}assault\u{0020}on\u{0020}the\u{0020}Third\u{0020}Laboratory.\u{0020}However,\u{0020}right\u{0020}now,\u{0020}the\u{0020}giant\u{0020}serpent\u{0020}Jormungand\u{0020}is\u{0020}our\u{0020}biggest\u{0020}obstacle.", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_2-12", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "救世主", "0", "\u{0020}\u{0020}第三研究院防卫队的队长，为了保护核心区的核心，启动了防御系统，使得我们有二十四小时的准备时间来攻破第三研究院，但眼下，被命名为【耶梦加得】的巨蛇是我们目前最大的阻碍。", "0", "0", "0", "0", "0"},
[100227] = {id = 100227, scroll = 100020, type = 2, teacheid = 0, name = "5-28", cname = "Interlude\u{0020}II", plot_first = "2_13", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100226", open = "100228_100021", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "The\u{0020}members\u{0020}of\u{0020}the\u{0020}Third\u{0020}Laboratory\u{0020}Defense\u{0020}Squad\u{0020}begin\u{0020}losing\u{0020}their\u{0020}memories\u{0020}due\u{0020}to\u{0020}the\u{0020}haze.\u{0020}But\u{0020}there\u{0020}is\u{0020}something—some\u{0020}force,\u{0020}some\u{0020}idea,\u{0020}or\u{0020}some\u{0020}will—that\u{0020}keeps\u{0020}them\u{0020}holding\u{0020}on,\u{0020}enduring\u{0020}through\u{0020}it\u{0020}all...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_2-13", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-13", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "幕间Ⅱ", "0", "\u{0020}\u{0020}第三研究院防卫队的成员们在苍雾的影响下渐渐失去了自己的记忆，但是，不知道有什么力量、什么东西、什么想法，让她们一直在苦苦支撑着、支撑着……", "0", "0", "0", "0", "0"},
