[100245] = {id = 100245, scroll = 100021, type = 0, teacheid = 0, name = "6-18", cname = "Haze\u{0020}Expansion", plot_first = "2_17", plot_last = "0", map = "haizhan_baitian", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100244", open = "100246_100021", player = "0", monster = "210017_3_48_0_3_9_1_0_100041_4500_0_100241_1600_0;230004_2_54_0_3_11_1_0_100041_4500_0_100241_1600_0;230001_2_54_0_3_1_1_0_100041_4500_0_100241_1600_0;210012_2_54_0_3_13_1_0_100041_4500_0_100241_1600_0;220011_2_54_0_3_10_1_0_100041_4500_0_100241_1600_0;210004_2_54_0_3_7_1_0_100041_4500_0_100241_1600_0;210017_3_48_0_3_16_1_0_100041_4500_0_100241_1600_0;210004_2_54_0_3_5_1_0_100041_4500_0_100241_1600_0;210004_2_54_0_3_18_1_0_100041_4500_0_100241_1600_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "1_100000_30,1_110082_5,1_100001_3000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "The\u{0020}haze\u{0020}continues\u{0020}to\u{0020}spread,\u{0020}occupying\u{0020}more\u{0020}territory.\u{0020}Once\u{0020}the\u{0020}mist\u{0020}engulfs\u{0020}the\u{0020}entire\u{0020}city,\u{0020}the\u{0020}situation\u{0020}will\u{0020}become\u{0020}dire.\u{0020}The\u{0020}expansion\u{0020}of\u{0020}the\u{0020}haze\u{0020}means\u{0020}that\u{0020}Jormungand\u{0020}is\u{0020}growing\u{0020}stronger.\u{0020}We\u{0020}need\u{0020}to\u{0020}speed\u{0020}up\u{0020}the\u{0020}process\u{0020}of\u{0020}taking\u{0020}down\u{0020}Jormungand...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-17", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "苍雾扩张", "0", "\u{0020}\u{0020}苍雾还在继续扩张所侵占的领土，一旦雾气扩散至整个城市，情势就会变得险峻，苍雾的扩张，代表着耶梦加得正在成长，我们需要加快击破【耶梦加得】的速度了……", "0", "0", "0", "0", "0"},
