[100249] = {id = 100249, scroll = 100021, type = 0, teacheid = 0, name = "6-22", cname = "Return", plot_first = "2_18", plot_last = "0", map = "haizhan_baitian", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100248", open = "100250_100021", player = "0", monster = "210017_3_48_0_3_4_1_0_100041_4600_0_100241_1600_0;210012_2_54_0_3_8_1_0_100041_4600_0_100241_1600_0;230004_2_54_0_3_11_1_0_100041_4600_0_100241_1600_0;210017_3_48_0_3_12_1_0_100041_4600_0_100241_1600_0;220011_2_54_0_3_2_1_0_100041_4600_0_100241_1600_0;230001_2_55_0_3_1_1_0_100041_4600_0_100241_1600_0;210004_2_55_0_3_5_1_0_100041_4600_0_100241_1600_0;210004_2_55_0_3_13_1_0_100041_4600_0_100241_1600_0;210004_2_55_0_3_6_1_0_100041_4600_0_100241_1600_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "1_100000_30,1_110072_5,1_100001_3000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "Before\u{0020}entering\u{0020}the\u{0020}haze,\u{0020}all\u{0020}Navigators\u{0020}are\u{0020}ordered\u{0020}to\u{0020}remain\u{0020}outside\u{0020}the\u{0020}haze.\u{0020}Only\u{0020}our\u{0020}squad\u{0020}ignore\u{0020}this\u{0020}order.\u{0020}Though\u{0020}lost\u{0020}in\u{0020}it,\u{0020}I\u{0020}can\u{0020}guide\u{0020}us.\u{0020}The\u{0020}hunt\u{0020}for\u{0020}Jormungand\u{0020}officially\u{0020}begins.", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-18", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "重返", "0", "\u{0020}\u{0020}在进入苍雾之前，所有的领航都被下达了停留在苍雾外的指令，只有我们小队无视了这一指令，进入了苍雾，即使大家在苍雾中迷失，也有我可以引导方向，【耶梦加得】讨伐战，正式开始了。", "0", "0", "0", "0", "0"},
