[100252] = {id = 100252, scroll = 100021, type = 15, teacheid = 0, name = "6-25", cname = "Fishing", plot_first = "2_19", plot_last = "0", map = "haizhan_baitian", bgm = "16-Battle-Jormungand_MP3", unlock = "0_1", front = "100251", open = "100253_100021", player = "0", monster = "600002_4_65_1_4_8_1_0_100155_7000_0_100355_9500_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "4_500002_1,1_110031_1,1_100000_50,1_100001_5000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "All\u{0020}nearby\u{0020}Sins\u{0020}have\u{0020}been\u{0020}eliminated,\u{0020}but\u{0020}there's\u{0020}no\u{0020}sign\u{0020}of\u{0020}Jormungand.\u{0020}I\u{0020}plan\u{0020}to\u{0020}use\u{0020}myself\u{0020}as\u{0020}bait,\u{0020}activating\u{0020}Synesthesia\u{0020}to\u{0020}draw\u{0020}Jormungand\u{0020}out.\u{0020}As\u{0020}a\u{0020}Navigator,\u{0020}I'm\u{0020}supposed\u{0020}to\u{0020}do\u{0020}so...\u{0020}Soon,\u{0020}Jormungand\u{0020}takes\u{0020}the\u{0020}bait.", prohibit = "220307;210806;211603;211604", scrollmappos = "0", prohibitskill = "220307;210806;211603;211604", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-19", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 1, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "临高垂钓", "0", "\u{0020}\u{0020}附近的原罪已经全部消灭，但是，没有发现耶梦加得的踪迹，我打算用自己做诱饵，用【通感】去触动耶梦加得，我是一位领航，这就是一位领航该做的事……随后【耶梦加得】果然上钩了……", "0", "0", "0", "0", "0"},
[100253] = {id = 100253, scroll = 100021, type = 2, teacheid = 0, name = "6-26", cname = "World\u{0020}Serpent", plot_first = "2_20", plot_last = "0", map = "0", bgm = "20-Battle-Warehouse2_MP3", unlock = "0_1", front = "100252", open = "100300_100030", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "The\u{0020}battle\u{0020}with\u{0020}Jormungand\u{0020}has\u{0020}ended...\u{0020}We\u{0020}manage\u{0020}to\u{0020}kill\u{0020}it\u{0020}before\u{0020}it\u{0020}could\u{0020}gather\u{0020}its\u{0020}energy.\u{0020}As\u{0020}we\u{0020}near\u{0020}the\u{0020}Third\u{0020}Laboratory,\u{0020}Dolores'\u{0020}communicator\u{0020}receives\u{0020}a\u{0020}message...\u{0020}At\u{0020}that\u{0020}moment,\u{0020}she\u{0020}has\u{0020}no\u{0020}idea\u{0020}what\u{0020}it\u{0020}means...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_2-20", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_2-20", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "尘世巨蟒", "0", "\u{0020}\u{0020}与【耶梦加得】的战斗结束了……我们抢先杀死了正在汇聚能量的【耶梦加得】，在靠近第三研究院的时候，多洛莉丝的通讯器里接收到了一个通讯……这个时候的她，还不知道这意味着什么……", "0", "0", "0", "0", "0"},
[100300] = {id = 100300, scroll = 100030, type = 2, teacheid = 0, name = "7-1", cname = "Near\u{0020}the\u{0020}Other\u{0020}Shore", plot_first = "3_1", plot_last = "0", map = "0", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100253", open = "100301_100030", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10,1_100001_2000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "The\u{0020}Danube\u{0020}Special\u{0020}Joint\u{0020}Task\u{0020}Force\u{0020}is\u{0020}escorting\u{0020}Dolores\u{0020}to\u{0020}the\u{0020}Third\u{0020}Laboratory,\u{0020}with\u{0020}the\u{0020}goal\u{0020}of\u{0020}obtaining\u{0020}Greed's\u{0020}Core.\u{0020}Meanwhile,\u{0020}Envy\u{0020}begins\u{0020}to\u{0020}make\u{0020}contact\u{0020}with\u{0020}Nevaeh...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_3-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_3-1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "近临彼岸", "0", "\u{0020}\u{0020}多瑙特别联合部队护送着多洛莉丝继续前往第三研究室，目标是贪婪核心，而同一时间原罪【嫉妒】开始与【逆爱】接触……", "0", "0", "0", "0", "0"},
