[100322] = {id = 100322, scroll = 100030, type = 0, teacheid = 0, name = "7-23", cname = "Daze", plot_first = "3_12", plot_last = "0", map = "yanjiushi", bgm = "4-Battle-moon_MP3", unlock = "0_1", front = "100321", open = "100323_100030", player = "0", monster = "200010_3_64_0_4_14_1_0_100043_5100_0_100043_1700_0;220015_3_60_0_4_13_1_0_100043_5100_0_100243_1700_0;220015_3_60_0_4_10_1_0_100043_5100_0_100243_1700_0;210001_3_64_0_3_9_1_0_100043_5100_0_100043_1700_0;210001_3_64_0_4_8_1_0_100043_5100_0_100043_1700_0;200007_3_60_0_4_17_1_0_100043_5100_0_100243_1700_0;210000_3_60_0_4_11_1_0_100043_5100_0_100243_1700_0;200007_3_64_0_4_2_1_0_100043_5100_0_100243_1700_0;200007_3_64_0_4_4_1_0_100043_5100_0_100243_1700_0", consume = "4_100001_16", frequency = 0, condition = "0_9_1,2_40_19,0_2_12", reward = "1_100000_30,1_110080_5,1_100001_3000", drop = "0", victory = "4_100000_160,1_100001_640", roleexp = "4_100002_160", failure = "4_100001_16", introduction = "As\u{0020}we\u{0020}move\u{0020}deeper\u{0020}into\u{0020}the\u{0020}laboratory,\u{0020}the\u{0020}haze\u{0020}grows\u{0020}thicker,\u{0020}and\u{0020}our\u{0020}energy\u{0020}reserves\u{0020}are\u{0020}running\u{0020}low.\u{0020}At\u{0020}that\u{0020}moment,\u{0020}I\u{0020}suddenly\u{0020}\"see\"\u{0020}strange\u{0020}visions...", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "icon_storm_battle", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_3-12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "恍惚", "0", "\u{0020}\u{0020}我们步入了研究室的深层，苍雾越来越浓厚，大家的能源已经消耗过半了，此时的我忽然“看到”了奇异的画面……", "0", "0", "0", "0", "0"},
