[900000] = {id = 900000, scroll = 900000, type = 2, teacheid = 0, name = "1-1", cname = "舊夢初醒", plot_first = "n_1", plot_last = "0", map = "0", bgm = "Battle-ziyuan_MP3", unlock = "1_930000", front = "100039", open = "900001_900000", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_50,1_100001_3000", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "我從噩夢中醒來，但是眼前卻不是那個熟悉的世界。甚至連我說話的聲音都消失了。一個奇怪的女僕告訴我這這一切都是高等原罪【BOSS】在搞鬼。可是僅憑我們兩人該如何對抗原罪呢？", prohibit = "0", scrollmappos = "1597,-1319", prohibitskill = "0", picture = "dialog_n-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "dialog_n-1", reserve = "0", dangerousenemy = "0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "1_400000_1", energycondition = "0", timelocal = "0", itembonus = "0", "0", "\u{0020}\u{0020}我从噩梦中醒来，但是眼前却不是那个熟悉的世界。甚至连我说话的声音都消失了。一个奇怪的女仆告诉我这这一切都是高等原罪【BOSS】在搞鬼。可是仅凭我们两人该如何对抗原罪呢？", "0", "0", "0", "0", "0", "0"},
