[900758] = {id = 900758, scroll = 900709, type = 2, teacheid = 0, name = "1", cname = "Marriage\u{0020}Fraudster", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_1", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "0", open = "900759_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "一名少女找到了你，並自稱是你未來的妻子，這實在讓人難以相信。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_1", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900759] = {id = 900759, scroll = 900709, type = 2, teacheid = 0, name = "2", cname = "Problem\u{0020}Child", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_2", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900758", open = "900760_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "克莉絲蒂娜和洛尼絲就九十九環的問題進行了探討，洛尼絲對於九十九環擅自行動表示了不滿，而克莉絲蒂娜試圖包庇九十九環。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_2", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900760] = {id = 900760, scroll = 900709, type = 2, teacheid = 0, name = "3", cname = "Popular\u{0020}with\u{0020}Girls", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_3", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900759", open = "900761_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "你和九十九環準備迎擊原罪的入侵，九十九環稱自己已經看到了這場戰鬥會發生的所有事情。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_3", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900761] = {id = 900761, scroll = 900709, type = 2, teacheid = 0, name = "4", cname = "Superfluous\u{0020}Gentle\u{0020}Nature", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_4", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900760", open = "900762_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "為了對自己的能力有更深入的瞭解，九十九環接受了史蒂芬妮的實驗計畫，與此同時史蒂芬妮有一件重要的事情要交給你。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_4", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900762] = {id = 900762, scroll = 900709, type = 2, teacheid = 0, name = "5", cname = "Relocation\u{0020}Plan", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_5", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900761", open = "900763_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "你與多洛莉絲，克莉絲蒂娜，九十九環開會討論，就第三研究室遷往卡佳一事的可能性進行了探討，在會議時，九十九環看到了壞結局。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_5", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900763] = {id = 900763, scroll = 900709, type = 2, teacheid = 0, name = "6", cname = "One\u{0020}for\u{0020}Death", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_6", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900762", open = "900764_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "會議不歡而散，九十九環與你討論壞結局的對策。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_6", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900764] = {id = 900764, scroll = 900709, type = 2, teacheid = 0, name = "7", cname = "Last\u{0020}Will\u{0020}Party", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_7", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900763", open = "900765_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "九十九環拜託你把大家呼喚過來，打算從一次夜談中更深入地獲得未來的資訊——這是她預知未來的缺陷，需要通過情報來構建未來。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_7", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900765] = {id = 900765, scroll = 900709, type = 2, teacheid = 0, name = "8", cname = "\"Captain\"", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_8", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900764", open = "900766_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "就和安潔莉卡隊長一樣，現第三研究室防衛班的隊長多洛莉絲，也做好了迎接自己死亡的心理準備。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_8", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900766] = {id = 900766, scroll = 900709, type = 2, teacheid = 0, name = "9", cname = "Second\u{0020}Natural\u{0020}Disaster", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_9", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900765", open = "900767_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "九十九環繼續和你講述她所看到的，你所不知道的未來。在得到更多的情報後，她發現自己和你並未出現在這段未來中……", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_9", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900767] = {id = 900767, scroll = 900709, type = 2, teacheid = 0, name = "10", cname = "\"Predicting\u{0020}the\u{0020}Future\"", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_10", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900766", open = "900768_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "高等原罪貪婪開始了她的第二次行動，九十九環和史蒂芬妮就預知未來這個能力的缺陷開始了討論，史蒂芬妮認為九十九環的能力並不是預知未來而是觀測一條過去的世界線。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_10", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900768] = {id = 900768, scroll = 900709, type = 2, teacheid = 0, name = "11", cname = "Her\u{0020}Sword", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_11", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900767", open = "900769_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "你把九十九環的預知帶給另外三個人，多洛莉絲決定行動起來，亞爾薇特和克莉絲蒂娜處理完最後的工作後也將幫助多洛莉絲。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_11", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900769] = {id = 900769, scroll = 900709, type = 2, teacheid = 0, name = "12", cname = "\"Reverse\u{0020}Transcription\u{0020}Beam\"", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_11e", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900768", open = "900770_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "亞爾薇特和克莉絲蒂娜處理資料的時候發現了一組異常資料，這組異常資料揭示了【逆轉錄光束】的一角，亞爾薇特找到了“自殺”的契機，為了再次觀測到【逆轉錄光束】，她決定加入這次行動。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_12", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900770] = {id = 900770, scroll = 900709, type = 2, teacheid = 0, name = "13", cname = "Those\u{0020}Deserving\u{0020}Death", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_12", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900769", open = "900771_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "紅博士，克莉絲蒂娜，亞爾薇特在給多洛莉絲的強化方案上起了分歧，亞爾薇特決定把自己最為重要的原型機託付多洛莉絲，克莉絲蒂娜看出了亞爾薇特在安排自己的遺產。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_13", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900771] = {id = 900771, scroll = 900709, type = 2, teacheid = 0, name = "14", cname = "A\u{0020}Third\u{0020}Farewell", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_13", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900770", open = "900772_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "九十九環為了看到更清晰的未來，即使要承受莫大的痛苦也決定啟用維生艙，但是——她在未來看到自己死在了你的懷裡。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_14", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900772] = {id = 900772, scroll = 900709, type = 2, teacheid = 0, name = "15", cname = "My\u{0020}Special\u{0020}Treasure", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_14", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900771", open = "900773_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "你找到了消沉的九十九環，你不知道她看到了什麼未來讓她受到了這麼大的打擊，但是這並不妨礙九十九環借你的膝蓋用一用。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_15", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900773] = {id = 900773, scroll = 900709, type = 2, teacheid = 0, name = "16", cname = "Overwrite\u{0020}the\u{0020}Future", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_15", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900772", open = "900774_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "克莉絲蒂娜找到了九十九環，告知了她多洛莉絲和亞爾薇特的情況，她希望九十九環能救下亞爾薇特，於是九十九就在你通感的幫助下，開始透支自己，也透支未來。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_16", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
[900774] = {id = 900774, scroll = 900709, type = 2, teacheid = 0, name = "17", cname = "BAD\u{0020}END\u{0020}No.99", plot_first = "Huo@dongPlot/CuoShiHuiHuan/bzn1_16", plot_last = "0", map = "0", bgm = "0", unlock = "0,1", front = "900773", open = "900775_900709", player = "0", monster = "0", consume = "4_100001_0", frequency = 0, condition = "0", reward = "1_100000_10", drop = "0", victory = "0", roleexp = "0", failure = "0", introduction = "你看見了九十九環極力想要隱藏的未來——那是她與你訣別，死去的未來。你與她定下了約定，一定會拯救她，同時多洛莉絲的新戰鬥服也完成了。", prohibit = "0", scrollmappos = "0", prohibitskill = "0", picture = "dialog_s-1", npctype = 0, npcbanmove = "0", playnumber = 9, recomlevel = 0, bgpicture = "Activity/HalfAnniversary/Img_Level_b1_17", reserve = "0", dangerousenemy = "0_0", npcheads = "0", promptdialog = "0", returnfloorid = 0, continuouscombattype = 0, activitypreview2 = "0", energycondition = "0", timelocal = "0", itembonus = "0", "0", "0", "0", "0", "0", "0", "0", "0"},
